        '2026-08': 861476.46, '2026-09': 860664.11, '2026-10': 869234.95
    }
    vals = list(known_mrr.values())
    xs = np.arange(len(vals))
    coeffs = np.polyfit(xs, vals, 1)
    slope, intercept = coeffs
    for i, label in enumerate(['2026-11', '2026-12', '2027-01']):
        x_new = len(vals) + i
        forecast_val = float(slope * x_new + intercept)
        result['forecast_points'].append({'period': label, 'value': round(forecast_val, 2)})
