try:
    df_clean = df[(df['row_kind'] != 'test') & (df['currency'] == 'USD')].copy()
except Exception:
    df_clean = df.copy()

metric_cols = ['interval_count', 'unit_amount', 'quantity', 'discount_pct', 'mrr']
seg_cols = ['plan', 'status', 'segment']
date_col = 'created'

# EDA
try:
    for col in metric_cols:
        s = df_clean[col].dropna()
        result['eda_summary'][col] = {
            'mean': float(s.mean()), 'std': float(s.std()),
            'min': float(s.min()), 'max': float(s.max()),
            'median': float(s.median()), 'count': int(s.count())
        }
except Exception:
    pass

# CORRELATIONS
try:
    num_df = df_clean[metric_cols].dropna()
    for i, c1 in enumerate(metric_cols):
        for c2 in metric_cols[i+1:]:
            pair = num_df[[c1, c2]].dropna()
            if len(pair) >= 30:
                r = float(pair[c1].corr(pair[c2]))
                if abs(r) >= 0.2:
                    result['correlations'][f'{c1}__{c2}'] = round(r, 4)
except Exception:
    pass

# SEGMENTATION
try:
    for seg in seg_cols:
        for metric in metric_cols:
            grp = df_clean.groupby(seg)[metric].mean()
            top = grp.nlargest(10)
            result['segments'].append({
                'segment_column': seg, 'metric_column': metric,
                'aggregation': 'mean', 'label': None,
                'results': [{'name': str(k), 'value': round(float(v), 4)} for k, v in top.items()]
            })
    # count by segment
    for seg in seg_cols:
        grp = df_clean.groupby(seg)['mrr'].count()
        result['segments'].append({
            'segment_column': seg, 'metric_column': 'mrr',
            'aggregation': 'count', 'label': 'subscription_count',
            'results': [{'name': str(k), 'value': int(v)} for k, v in grp.items()]
        })
    # in_force_now MRR by segment
    if 'in_force_now' in df_clean.columns:
        inf = df_clean[df_clean['in_force_now'] == 'yes']
        for seg in seg_cols:
            grp = inf.groupby(seg)['mrr'].sum()
            result['segments'].append({
                'segment_column': seg, 'metric_column': 'mrr',
                'aggregation': 'sum', 'label': 'mrr_in_force',
                'results': [{'name': str(k), 'value': round(float(v), 2)} for k, v in grp.items()]
            })
except Exception:
    pass

# ANOMALIES
try:
    import numpy as np
    anomaly_records = []
    anom_cols = ['unit_amount', 'quantity', 'discount_pct', 'mrr']
    for col in anom_cols:
        s = df_clean[col].dropna()
        if s.nunique() < 5:
            continue
        skew = float(s.skew())
        if abs(skew) > 2:
            shift = max(0, -s.min())
            s_t = np.log1p(s + shift)
        else:
            s_t = s.copy()
            shift = 0
        q1, q3 = s_t.quantile(0.25), s_t.quantile(0.75)
        iqr = q3 - q1
        lo, hi = q1 - 3*iqr, q3 + 3*iqr
        flagged = s_t[(s_t < lo) | (s_t > hi)]
        if len(flagged) / len(s_t) > 0.05:
            anomaly_records.append({
                'column': col, 'row_index': None, 'value': None,
                'expected_range': 'heavy-tailed distribution',
                'severity': 'low',
                'explanation': f'{col} flags >5% of values as extreme; heavy-tailed distribution, not anomalies'
            })
            continue
        lo_orig = float(np.expm1(lo) - shift) if abs(skew) > 2 else float(lo)
        hi_orig = float(np.expm1(hi) - shift) if abs(skew) > 2 else float(hi)
        exp_range = f'[{lo_orig:.2f}, {hi_orig:.2f}]'
        for idx in flagged.index:
            orig_val = float(s.loc[idx])
            t_val = float(s_t.loc[idx])
            dist_hi = (t_val - (q3 + 5*iqr))
            dist_lo = ((q1 - 5*iqr) - t_val)
            if dist_hi > 0 or dist_lo > 0:
                sev = 'critical'
            elif (t_val > q3 + 4*iqr) or (t_val < q1 - 4*iqr):
                sev = 'high'
            else:
                sev = 'medium'
            anomaly_records.append({
                'column': col, 'row_index': int(idx), 'value': orig_val,
                'expected_range': exp_range, 'severity': sev,
                'explanation': f'{col} value {orig_val:.2f} lies outside expected range {exp_range}'
            })
    anomaly_records.sort(key=lambda x: ['critical','high','medium','low'].index(x['severity']))
    result['anomalies'] = anomaly_records[:25]
except Exception:
    pass

# TRENDS
try:
    import numpy as np
    df_clean[date_col] = pd.to_datetime(df_clean[date_col], errors='coerce')
    df_t = df_clean.dropna(subset=[date_col]).copy()
    df_t['ym'] = df_t[date_col].dt.to_period('M')
    for metric in ['mrr', 'unit_amount', 'quantity', 'discount_pct']:
        monthly = df_t.groupby('ym')[metric].mean().sort_index()
        if len(monthly) >= 2:
            pct = float((monthly.iloc[-1] - monthly.iloc[0]) / monthly.iloc[0] * 100) if monthly.iloc[0] != 0 else 0.0
            direction = 'up' if pct > 1 else ('down' if pct < -1 else 'flat')
            result['trends'].append({
                'column': metric, 'period': 'MoM', 'direction': direction,
                'pct_change': round(pct, 2), 'segment': None
            })
    # MRR trend by plan
    for plan_val in df_t['plan'].dropna().unique():
        sub = df_t[df_t['plan'] == plan_val].groupby('ym')['mrr'].mean().sort_index()
        if len(sub) >= 2:
            pct = float((sub.iloc[-1] - sub.iloc[0]) / sub.iloc[0] * 100) if sub.iloc[0] != 0 else 0.0
            direction = 'up' if pct > 1 else ('down' if pct < -1 else 'flat')
            result['trends'].append({
                'column': 'mrr', 'period': 'MoM', 'direction': direction,
                'pct_change': round(pct, 2), 'segment': str(plan_val)
            })
except Exception:
    pass

